        if (!ProbeK.useRule()) return inferToday(args, appliedThing, envForInference);
        Simple_fcn r = null;
        try {
            r = inferRule(args, appliedThing, envForInference);
        }
        catch (RuntimeException ex) {
            r = null;
        }
        catch (EmptyLatticeIntervalError ex) {
            r = null;
        }
        return r != null ? r : inferToday(args, appliedThing, envForInference);
    }
    /* The top level: today's answer and the rule's, each difference written. */
    Simple_fcn today = null;
    RuntimeException todayEx = null;
    Boolean old = ProbeK.force(Boolean.FALSE);
    try {
