    /* The positions, and the first pass. */
    Map<String, List<FValue>> lone = new LinkedHashMap<String, List<FValue>>();
    Set<String> mentionedElsewhere = new HashSet<String>();
    Iterator<Param> pit = params.iterator();
    Param p = null;
