            return null;
        }
        Type ty = NodeUtil.optTypeOrPatternToType(t).unwrap();
        if (ty instanceof VarType && typeParamNames.contains(NodeUtil.nameString(((VarType) ty).getName()))) {
            String n = NodeUtil.nameString(((VarType) ty).getName());
            List<FValue> l = lone.get(n);
            if (l == null) lone.put(n, l = new ArrayList<FValue>());
            l.add(a);
            continue;
