        for (StaticParam tp : rechecks) {
            FType t = abm.get(NodeUtil.getName(tp));
            if (t == null) t = BottomType.ONLY;
            for (Type tr : tp.getExtendsClause()) t.unify(envForInference, tp_set, abm, tr);
