    if (fargs == null) return null;
    List<FType> dom = sfcn.getDomain();
    for (int j = 0; j < fargs.size(); j++) {
        if (!Coercions.admits(Useful.clampedGet(dom, j).deRest(), fargs.get(j))) return null;
    }
