}

/* The VarType of the lone parameter n, as some parameter declares it. */
private static Type makeVar(String n, List<Param> params) {
    for (Param p : params) {
        Option<TypeOrPattern> t = p.getIdType();
        if (t.isSome()) {
            Type ty = NodeUtil.optTypeOrPatternToType(t).unwrap();
            if (ty instanceof VarType && NodeUtil.nameString(((VarType) ty).getName()).equals(n)) return ty;
        }
    }
    throw new IllegalStateException("no parameter of type " + n);
}

/* The names of tp_set that the type ty mentions. */
static Set<String> mentions(Type ty, final Set<String> tp_set) {
    final Set<String> found = new HashSet<String>();
    ty.accept(new NodeDepthFirstVisitor_void() {
        @Override
        public void forVarTypeOnly(VarType that) {
            String n = NodeUtil.nameString(that.getName());
            if (tp_set.contains(n)) found.add(n);
        }

        @Override
        public void forIntRefOnly(IntRef that) {
            String n = NodeUtil.nameString(that.getName());
            if (tp_set.contains(n)) found.add(n);
        }

        @Override
        public void forBoolRefOnly(BoolRef that) {
            String n = NodeUtil.nameString(that.getName());
            if (tp_set.contains(n)) found.add(n);
        }

        @Override
        public void forOpArgOnly(OpArg that) {
            found.addAll(tp_set.contains(that.toString()) ? Collections.singleton(that.toString())
                                                         : Collections.<String>emptySet());
        }
    });
    return found;
}

/**
 * The narrowest type for the lone type parameter n, or null: among the arguments' run-time
 * types, their supertypes, the types a coercion takes them into and n's plain bounds, the
 * types that every argument matches or converts into and that n's bounds admit, the one that
 * is a subtype of, or convertible into, every other.
 */
private static FType narrowest(String n, List<FValue> vals,
                               BoundingMap<String, FType, TypeLatticeOps> abm,
                               List<StaticParam> rechecks, Set<String> tp_set, Environment env,
                               List<FType> bounds, Environment within) {
    LinkedHashSet<FType> cands = new LinkedHashSet<FType>();
    for (FValue v : vals) {
        FType t = v.type();
        cands.add(t);
        cands.addAll(t.getTransitiveExtends());
    }
    for (FValue v : vals) cands.addAll(Coercions.coercionTargets(v, within));
    if (bounds != null) cands.addAll(bounds);
    List<FType> ok = new ArrayList<FType>();
    for (FType c : cands) {
        if (c instanceof BottomType || c instanceof FTypeTop) continue;
        boolean all = true;
        for (FValue v : vals) {
            if (!Coercions.admits(c, v)) {
                all = false;
                break;
            }
        }
        if (!all) continue;
        BoundingMap<String, FType, TypeLatticeOps> trial = abm.copy();
        try {
            trial.joinPut(n, c);
            if (rechecks != null) {
                for (StaticParam tp : rechecks) {
                    if (!NodeUtil.getName(tp).equals(n)) continue;
                    for (Type tr : tp.getExtendsClause()) c.unify(env, tp_set, trial, tr);
                }
            }
        }
        catch (RuntimeException ex) {
            continue;
        }
        catch (EmptyLatticeIntervalError ex) {
            continue;
        }
        ok.add(c);
    }
    FType best = null;
    for (FType c : ok) {
        boolean narrower = true;
        for (FType d : ok) {
            if (d != c && !c.subtypeOf(d) && !Coercions.convertsInto(c, d)) {
                narrower = false;
                break;
            }
        }
        if (narrower) {
            if (best != null && best != c) return null;   // two: none is the narrowest
            best = c;
        }
    }
    return best;
}

