public static Simple_fcn inferAndInstantiateGenericFunction(List<FValue> args,
                                                            GenericFunctionOrMethod appliedThing,
                                                            Environment envForInference) throws ProgramError {
    if (!ProbeK.on()) return inferToday(args, appliedThing, envForInference);
    if (ProbeK.nested()) {
        if (!ProbeK.useRule()) return inferToday(args, appliedThing, envForInference);
        Simple_fcn r = null;
        try {
            r = inferRule(args, appliedThing, envForInference);
        }
        catch (RuntimeException ex) {
            r = null;
        }
        catch (EmptyLatticeIntervalError ex) {
            r = null;
        }
        return r != null ? r : inferToday(args, appliedThing, envForInference);
    }
    /* The top level: today's answer and the rule's, each difference written. */
    Simple_fcn today = null;
    RuntimeException todayEx = null;
    Boolean old = ProbeK.force(Boolean.FALSE);
    try {
        today = inferToday(args, appliedThing, envForInference);
    }
    catch (RuntimeException ex) {
        todayEx = ex;
    }
    finally {
        ProbeK.restore(old);
    }
    Simple_fcn rule = null;
    String ruleNote = "";
    old = ProbeK.force(Boolean.TRUE);
    try {
        rule = inferRule(args, appliedThing, envForInference);
    }
    catch (RuntimeException ex) {
        ruleNote = " rule-threw " + firstLine(ex);
    }
    catch (EmptyLatticeIntervalError ex) {
        ruleNote = " rule-threw EmptyLatticeInterval";
    }
    catch (StackOverflowError ex) {
        ruleNote = " rule-threw StackOverflowError";
    }
    finally {
        ProbeK.restore(old);
    }
    String t = today != null ? describeInstance(today, args) : "ERROR " + firstLine(todayEx);
    String r = rule != null ? describeInstance(rule, args) : "TODAY'S" + ruleNote;
    if (rule != null && !t.equals(r)) {
        ProbeK.log("INFER", appliedThing + "\targs " + argTypes(args) + "\ttoday " + t + "\trule " + r);
    }
    if (ProbeK.MODE == ProbeK.APPLY && rule != null) return rule;
    if (todayEx != null) throw todayEx;
    return today;
}

