public static String firstLine(Throwable ex) {
    if (ex == null) return "";
    String m = String.valueOf(ex.getMessage());
    int i = m.indexOf('\n');
    return ex.getClass().getSimpleName() + ": " + (i < 0 ? m : m.substring(0, i));
}

public static String argTypes(List<FValue> args) {
    StringBuilder b = new StringBuilder("(");
    for (FValue a : args) {
        if (b.length() > 1) b.append(",");
        FType t = a.type();
        b.append(t == null ? "?" : t.toString());
    }
    return b.append(")").toString();
}

